def calc(expr: str) -> int | str:
    n = len(expr)
    i = 0

    class _Err(Exception):
        pass

    def skip() -> None:
        nonlocal i
        while i < n and expr[i] == " ":
            i += 1

    def trunc_div(a: int, b: int) -> int:
        if b == 0:
            raise _Err
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    def parse_primary() -> int:
        nonlocal i
        skip()
        if expr[i] == "(":
            i += 1
            val = parse_add()
            skip()
            i += 1
            return val
        j = i
        while i < n and expr[i].isdigit():
            i += 1
        return int(expr[j:i])

    def parse_unary() -> int:
        nonlocal i
        # Each item is (sign, base): sign applies to base**rest, not to base
        # before the power. Consecutive leading minuses fold into one sign.
        # The tower is right-associative, so it is reduced from the right.
        items: list[tuple[int, int]] = []
        while True:
            skip()
            sign = 1
            while i < n and expr[i] == "-":
                sign = -sign
                i += 1
                skip()
            base = parse_primary()
            items.append((sign, base))
            skip()
            if i < n and expr[i] == "^":
                i += 1
                continue
            break
        sign, base = items[-1]
        val = -base if sign < 0 else base
        for sign, base in reversed(items[:-1]):
            if val < 0:
                raise _Err
            powered = base ** val
            val = -powered if sign < 0 else powered
        return val

    def parse_mul() -> int:
        nonlocal i
        left = parse_unary()
        while True:
            skip()
            if i < n and expr[i] in "*/%":
                op = expr[i]
                i += 1
                right = parse_unary()
                if op == "*":
                    left = left * right
                else:
                    q = trunc_div(left, right)
                    left = q if op == "/" else left - right * q
            else:
                return left

    def parse_add() -> int:
        nonlocal i
        left = parse_mul()
        while True:
            skip()
            if i < n and expr[i] in "+-":
                op = expr[i]
                i += 1
                right = parse_mul()
                left = left + right if op == "+" else left - right
            else:
                return left

    try:
        return parse_add()
    except _Err:
        return "error"
